package com.hospital.platform.bootstrap;
import org.springframework.amqp.core.*; import org.springframework.amqp.rabbit.annotation.RabbitListener; import org.springframework.amqp.rabbit.core.RabbitTemplate; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import com.hospital.platform.common.api.ApiResponse; import com.hospital.platform.common.trace.TraceId; import org.slf4j.Logger; import org.slf4j.LoggerFactory; import org.springframework.stereotype.Component;
@Configuration class MessagingConfiguration { static final String EXCHANGE="hospital.system.topic", QUEUE="hospital.system.test", ROUTING="system.test"; @Bean TopicExchange systemExchange(){return new TopicExchange(EXCHANGE,true,false);}@Bean Queue systemTestQueue(){return QueueBuilder.durable(QUEUE).build();}@Bean Binding systemBinding(){return BindingBuilder.bind(systemTestQueue()).to(systemExchange()).with(ROUTING);} }
@RestController @RequestMapping("/api/v1/system") class SystemEventController { private final RabbitTemplate rabbit; SystemEventController(RabbitTemplate rabbit){this.rabbit=rabbit;} @PostMapping("/test-events") @PreAuthorize("hasAuthority('system:event:publish')") ApiResponse<Void> publish(){rabbit.convertAndSend(MessagingConfiguration.EXCHANGE,MessagingConfiguration.ROUTING,"system-test:"+TraceId.get());return ApiResponse.success(null,TraceId.get());} }
@Component class SystemTestConsumer { private static final Logger log=LoggerFactory.getLogger(SystemTestConsumer.class); @RabbitListener(queues=MessagingConfiguration.QUEUE) void consume(String event){log.info("Consumed system test event, trace linked event={}",event);} }
